import { Card, Grid, Typography } from '@mui/material'

import ActivityPreviewCard from 'src/components/ActivityPreviewCard'
import SuspenseLoader from 'src/components/SuspenseLoader'

import { useGetPublicActivities } from 'src/hooks/api/activityHooks'

interface ActivityPreviewGridProps {
  clubId: number
}

const ActivityPreviewGrid = ({ clubId }: ActivityPreviewGridProps) => {
  const { data: activities, isLoading } = useGetPublicActivities(clubId)

  if (isLoading) {
    return <SuspenseLoader />
  }

  if (!activities || activities.length === 0) {
    return (
      <Card sx={{ p: 2 }}>
        <Typography color="text.secondary">아직 작성된 활동 기록이 없어요.</Typography>
      </Card>
    )
  }

  return (
    <Grid container spacing={2}>
      {activities.map(activity => (
        <Grid item xs={12} sm={6} md={6} key={activity.id}>
          <ActivityPreviewCard showClubInfo={false} activity={activity} />
        </Grid>
      ))}
    </Grid>
  )
}

export default ActivityPreviewGrid
